<?php
// Temporary, administrator-only deployment of the reviewed datetime module.
add_action('admin_menu', function () {
 add_submenu_page('tools.php','Kanonik Bilet Motoru Kurulumu','Kanonik Bilet Motoru Kurulumu','manage_options','mdg-datetime-module-install-20261003','mdg_datetime_module_install_20261003');
});
function mdg_datetime_module_install_20261003() {
 if (!current_user_can('manage_options')) { wp_die('Yetkisiz'); }
 nocache_headers();
 $dir=WP_PLUGIN_DIR.'/madagaskar-bilet-yonetimi';
 $main=$dir.'/madagaskar-bilet-yonetimi.php';
 $target=$dir.'/includes/class-mdg-ticket-session-datetime.php';
 $expected='f2ed98b99b5d65e210f386e1b244a85190ff3e75c999e53d2de0496cd9379e82';
 echo '<div class="wrap"><h1>Kanonik Bilet Motoru Kurulumu</h1><p>Yalnız doğrulanmış seans modülü dosyası eklenir.</p>';
 echo '<p>Ana motor SHA256: '.esc_html(hash_file('sha256',$main)).'</p>';
 echo '<p>Modül: '.(file_exists($target)?esc_html(hash_file('sha256',$target)):'HENÜZ YOK').'</p>';
 if (isset($_POST['install_module'])) {
  check_admin_referer('mdg_datetime_module_install_20261003');
  if (hash_file('sha256',$main)!=='991e3b78d8f9a9f2e36c3b689bd7c57c4175dafd9d4cade25f5095522abdc116') { wp_die('Ana kaynak değişmiş; durduruldu.'); }
  $code=base64_decode('',true);
  if (!$code || hash('sha256',$code)!==$expected) { wp_die('Kaynak doğrulaması başarısız.'); }
  if (file_exists($target)) {
   if (hash_file('sha256',$target)!==$expected) { wp_die('Mevcut dosya farklı; üzerine yazılmadı.'); }
  } else {
   $tmp=tempnam($dir.'/includes','mdg_datetime_');
   if (!$tmp || file_put_contents($tmp,$code)!==strlen($code) || !rename($tmp,$target)) { wp_die('Dosya yazılamadı; ana motor değiştirilmedi.'); }
  }
  if (function_exists('opcache_invalidate')) { opcache_invalidate($target,true); }
  echo '<p id="mdg-module-install-result">MODÜL KAYDEDİLDİ — SHA256 '.esc_html(hash_file('sha256',$target)).'</p>';
 }
 echo '<form method="post">'; wp_nonce_field('mdg_datetime_module_install_20261003');
 echo '<button class="button button-primary" name="install_module" value="1">Doğrulanmış modülü kaydet</button></form></div>';
}
